// Real-map data loader (generated by tools/build_map.py from the KU Sriracha area map).
import * as THREE from 'three';

export const MAP = {
  ready: false, meta: null, b: null, heights: null, nx: 0, nz: 0, step: 5, surface: null, sw: 0, sh: 0,
  landTex: null, sdfTex: null,
};

async function bitmap(url) {
  const blob = await fetch(url).then(r => { if (!r.ok) throw new Error('missing ' + url); return r.blob(); });
  return createImageBitmap(blob, { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
}
function pixels(bmp) {
  const c = document.createElement('canvas'); c.width = bmp.width; c.height = bmp.height;
  const x = c.getContext('2d', { willReadFrequently: true }); x.drawImage(bmp, 0, 0);
  return x.getImageData(0, 0, bmp.width, bmp.height).data;
}
function gpuTex(bmp) {
  const t = new THREE.Texture(bmp); t.flipY = false; t.colorSpace = THREE.NoColorSpace; t.generateMipmaps = true;
  t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter; t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping; t.needsUpdate = true; return t;
}

export async function loadMap(base = new URL('../data/', import.meta.url).href) {
  const [meta, hb, sb, lb, db] = await Promise.all([
    fetch(base + 'map.json').then(r => r.json()), bitmap(base + 'height.png'), bitmap(base + 'surface.png'), bitmap(base + 'landuse.png'), bitmap(base + 'sdf.png'),
  ]);
  MAP.meta = meta; MAP.b = meta.bounds; MAP.nx = meta.bounds.nx; MAP.nz = meta.bounds.nz; MAP.step = meta.bounds.step;
  const hp = pixels(hb); const H = new Float32Array(MAP.nx * MAP.nz);
  for (let i = 0; i < H.length; i++) H[i] = (hp[i * 4] * 256 + hp[i * 4 + 1]) / 100 - 50;
  MAP.heights = H;
  const sp = pixels(sb); MAP.sw = sb.width; MAP.sh = sb.height; const S = new Uint8Array(MAP.sw * MAP.sh);
  for (let i = 0; i < S.length; i++) S[i] = sp[i * 4];
  MAP.surface = S;
  MAP.landTex = gpuTex(lb); MAP.sdfTex = gpuTex(db);
  MAP.sdfPix = pixels(db); MAP.sdfW = db.width; MAP.sdfH = db.height; // CPU copy for geometry fitting (freed after the world is built)
  MAP.ready = true;
  return MAP;
}

// signed distance (m) to the road edge from the smoothed SDF (negative = on the road); channel 0 road, 1 walk
export function sdfAt(x, z, ch = 0) {
  const b = MAP.b, P = MAP.sdfPix; if (!P) return 99;
  let fx = (x - b.minX) / (b.maxX - b.minX) * MAP.sdfW - 0.5, fz = (z - b.minZ) / (b.maxZ - b.minZ) * MAP.sdfH - 0.5;
  fx = Math.max(0, Math.min(MAP.sdfW - 1.001, fx)); fz = Math.max(0, Math.min(MAP.sdfH - 1.001, fz));
  const ix = fx | 0, iz = fz | 0, tx = fx - ix, tz = fz - iz, W = MAP.sdfW;
  const g = (i, j) => P[((j * W) + i) * 4 + ch];
  const v = (g(ix, iz) * (1 - tx) + g(ix + 1, iz) * tx) * (1 - tz) + (g(ix, iz + 1) * (1 - tx) + g(ix + 1, iz + 1) * tx) * tz;
  return (v - 128) / 8;
}
export function groundHeight(x, z) {
  const b = MAP.b; if (!b) return 0;
  let fx = (x - b.minX) / MAP.step, fz = (z - b.minZ) / MAP.step;
  fx = Math.max(0, Math.min(MAP.nx - 1.001, fx)); fz = Math.max(0, Math.min(MAP.nz - 1.001, fz));
  const ix = Math.floor(fx), iz = Math.floor(fz), tx = fx - ix, tz = fz - iz;
  const H = MAP.heights, n = MAP.nx;
  const a = H[iz * n + ix], c = H[iz * n + ix + 1], d = H[(iz + 1) * n + ix], e = H[(iz + 1) * n + ix + 1];
  return (a * (1 - tx) + c * tx) * (1 - tz) + (d * (1 - tx) + e * tx) * tz;
}
// flatten the heightmap under a rectangle (used for sports fields, plazas, special structures)
export function flattenRect(x0, z0, x1, z1, h, blend = 10) {
  const b = MAP.b, n = MAP.nx;
  for (let iz = 0; iz < MAP.nz; iz++) {
    const z = b.minZ + iz * MAP.step; const dz = Math.max(z0 - z, 0, z - z1); if (dz > blend) continue;
    for (let ix = 0; ix < n; ix++) {
      const x = b.minX + ix * MAP.step; const dx = Math.max(x0 - x, 0, x - x1); if (dx > blend) continue;
      const d = Math.hypot(dx, dz); if (d > blend) continue;
      let t = 1 - d / blend; t = t * t * (3 - 2 * t);
      const k = iz * n + ix; MAP.heights[k] = MAP.heights[k] * (1 - t) + h * t;
    }
  }
}
export function inBounds(x, z) { const b = MAP.b; return x > b.minX + 5 && x < b.maxX - 5 && z > b.minZ + 5 && z < b.maxZ - 5; }
